use mermaid_rs_renderer::scene::prepare::blitter::surface_size::{min_row_bytes,compute_data_len,data_len_for_size};use tiny_skia_path::IntSize;use serde::Deserialize;use std::panic::AssertUnwindSafe;
#[derive(Debug,Deserialize)]struct Input{width:u32,height:u32,row_bytes:usize}#[derive(Deserialize)]struct Case{input:Input,result:(bool,Option<usize>,Option<usize>,Option<usize>)}#[derive(Deserialize)]struct Fixture{cases:Vec<Case>}
fn stub(e:&(dyn std::any::Any+Send))->bool{let s=e.downcast_ref::<&str>().copied().or_else(||e.downcast_ref::<String>().map(String::as_str)).unwrap_or("");s.contains("Unimplemented Root-frozen")}
#[test]fn original_storage_helper_integer_results(){let hook=std::panic::take_hook();std::panic::set_hook(Box::new(|_|{}));let f:Fixture=serde_json::from_str(include_str!("fixtures/borrowed-size.json")).unwrap();assert_eq!(f.cases.len(),567);let(mut mismatches,mut stubs,mut errors)=(0,0,0);for c in f.cases{let i=c.input;let r=std::panic::catch_unwind(||{if let Some(size)=IntSize::from_wh(i.width,i.height){(true,min_row_bytes(size).map(std::num::NonZeroUsize::get),compute_data_len(size,i.row_bytes),data_len_for_size(size))}else{(false,None,None,None)}});if let Err(e)=&r{stubs+=usize::from(stub(&**e));errors+=1;}mismatches+=usize::from(r.ok()!=Some(c.result));}std::panic::set_hook(hook);println!("567 actual original storage helper records / {mismatches} mismatches / {stubs} actual stub calls / {errors} errors");assert_eq!(mismatches,0);assert_eq!(stubs,0);assert_eq!(errors,0);}
#[test]fn all_three_size_helpers_are_implemented(){let hook=std::panic::take_hook();std::panic::set_hook(Box::new(|_|{}));let size=IntSize::from_wh(2,2).unwrap();let mut stubs=0;for method in 0..3{let r=std::panic::catch_unwind(AssertUnwindSafe(||match method{0=>{let _=min_row_bytes(size);},1=>{let _=compute_data_len(size,8);},_=>{let _=data_len_for_size(size);}}));if let Err(e)=r{stubs+=usize::from(stub(&*e));}}std::panic::set_hook(hook);println!("Three direct size helper witnesses / {stubs} actual stub calls");assert_eq!(stubs,0);}
